#include <iostream>
using namespace std;

struct Node {
    int data;
    int height;
    Node* left;
    Node* right;
    Node(int d) : data(d), height(1), left(nullptr), right(nullptr) {}
};

int getHeight(Node* node) {
    if (node == nullptr) {
        return 0;
    }
    return node->height;
}

int maxOf(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}

void updateHeight(Node* node) {
    node->height = 1 + maxOf(getHeight(node->left), getHeight(node->right));
}

Node* rotateLeft(Node* x) {
    Node* y = x->right;
    x->right = y->left;
    y->left = x;
    updateHeight(x);
    updateHeight(y);
    return y;
}

Node* rotateRight(Node* y) {
    Node* x = y->left;
    y->left = x->right;
    x->right = y;
    updateHeight(y);
    updateHeight(x);
    return x;
}

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    updateHeight(node);
    int balance = getHeight(node->left) - getHeight(node->right);
    if (balance > 1 && value < node->left->data) {
        return rotateRight(node);
    }
    if (balance < -1 && value > node->right->data) {
        return rotateLeft(node);
    }
    if (balance > 1 && value > node->left->data) {
        node->left = rotateLeft(node->left);
        return rotateRight(node);
    }
    if (balance < -1 && value < node->right->data) {
        node->right = rotateRight(node->right);
        return rotateLeft(node);
    }
    return node;
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    root = insert(root, 10);
    root = insert(root, 20);
    root = insert(root, 30);
    cout << "Root: " << root->data << endl;
    destroy(root);
    return 0;
}
